class LayerNorm(nn.LayerNorm):
    def forward(self, x: torch.Tensor):
        orig_type = x.dtype
        ret = super().forward(x.type(torch.float32))
        return ret.type(orig_type)

class QuickGELU(nn.Module):
    def forward(self, x: torch.Tensor):
        return x * torch.sigmoid(1.702 * x)

class ResidualAttentionBlock(nn.Module):
    def __init__(self, d_model: int, n_head: int, attn_mask: torch.Tensor = None, prompt_length=16,
                 text_layer=False, i=0, prompt_depth=0):
        super().__init__()

        self.attn = nn.MultiheadAttention(d_model, n_head)
        self.ln_1 = LayerNorm(d_model)
        self.mlp = nn.Sequential(OrderedDict([
            ("c_fc", nn.Linear(d_model, d_model * 4)),
            ("gelu", QuickGELU()),
            ("c_proj", nn.Linear(d_model * 4, d_model))
        ]))
        self.ln_2 = LayerNorm(d_model)
        self.text_layer = text_layer
        self.attn_mask = attn_mask
        self.prompt_length_half = prompt_length//3
        if i ==0 and i<=prompt_depth:
            self.attn_prompt = nn.MultiheadAttention(d_model, 1)
            self.prompts_dynamic_complete = nn.Parameter(nn.init.normal_(torch.empty(self.prompt_length_half, 1, d_model, dtype=torch.float), std=0.02))
            self.prompts_dynamic_image = nn.Parameter(nn.init.normal_(torch.empty(self.prompt_length_half, 1, d_model, dtype=torch.float), std=0.02))
            self.prompts_dynamic_text = nn.Parameter(nn.init.normal_(torch.empty(self.prompt_length_half, 1, d_model, dtype=torch.float), std=0.02))
        if i == 0:
            self.first_layer = True
        else:
            self.first_layer = False

    def attention(self, x: torch.Tensor):
        self.attn_mask = self.attn_mask.to(dtype=x.dtype, device=x.device) if self.attn_mask is not None else None
        return self.attn(x, x, x, need_weights=False, attn_mask=self.attn_mask)[0]

    def forward(self, inputs):
        x = inputs[0] # [length, batch, channel]
        batch_size = x.shape[1]
        compound_prompts_deeper = inputs[1]
        counter = inputs[2]
        missing_type = inputs[3]
        if len(compound_prompts_deeper) > 0:
            if counter == 0: # This condition for the first transformer layer of prompts
                if not (counter > len(compound_prompts_deeper) - 1):
                    if not self.first_layer:
                        visual_features = x[self.prompt_length_half*3:, :, :]
                    else:
                        visual_features = x
                    prompts_dynamic = []
                    for i_batch in range(len(missing_type)):
                        if missing_type[i_batch]==0:
                            prompts_dynamic.append(self.prompts_dynamic_complete)
                        elif missing_type[i_batch]==1:
                            prompts_dynamic.append(self.prompts_dynamic_image)
                        elif missing_type[i_batch]==2:
                            prompts_dynamic.append(self.prompts_dynamic_text)
                    prompts_dynamic = torch.cat(prompts_dynamic, 1)
                    # Dynamic Prompts: generated based on input features (visual_features) using self-attention
                    prompts_dynamic = self.attn_prompt(prompts_dynamic.to(x.get_device()), visual_features, visual_features, need_weights=False, attn_mask=None)[0]
                    prompts_staged_and_common = compound_prompts_deeper[counter] # Correlated and Modal-common prompts for this layer
                    prompts_staged_and_common = prompts_staged_and_common.permute(1, 0, 2)
                    x = torch.cat([prompts_staged_and_common, prompts_dynamic, visual_features], dim=0)
                    counter += 1
            else:
                if not (counter > len(compound_prompts_deeper) - 1):
                    if not self.first_layer:
                        features = x[self.prompt_length_half*3:, :, :]
                    else:
                        features = x
                    prompts_dynamic_and_common = x[self.prompt_length_half:self.prompt_length_half*3, :, :]
                    prompts = compound_prompts_deeper[counter] # Correlated prompts for this layer
                    prompts = prompts.permute(1, 0, 2)
                    x = torch.cat([prompts, prompts_dynamic_and_common, features], dim=0)
                    counter += 1
        x = x + self.attention(self.ln_1(x))
        x = x + self.mlp(self.ln_2(x))
        return [x, compound_prompts_deeper, counter, None]

class Transformer(nn.Module):
    def __init__(self, width: int, layers: int, heads: int, attn_mask: torch.Tensor = None, prompts_needed=0,
                 text_layer=False, prompt_length=None, prompt_depth=0):
        super().__init__()
        self.width = width
        self.layers = layers
        self.resblocks = nn.Sequential(*[ResidualAttentionBlock(width, heads, attn_mask, prompt_length, text_layer, i, prompt_depth)
                  for i in range(layers)])

    def forward(self, x: torch.Tensor): # x is expected to be a list [features, all_prompts, counter, missing_type]
        return self.resblocks(x)

class VisionTransformer(nn.Module):
    def __init__(self, input_resolution: int, patch_size: int, width: int, layers: int, heads: int, output_dim: int,
                 prompt_length, prompt_depth):
        super().__init__()
        self.input_resolution = input_resolution
        self.output_dim = output_dim
        self.prompt_length = prompt_length # Overall prompt length
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=width, kernel_size=patch_size, stride=patch_size, bias=False)
        scale = width ** -0.5
        self.class_embedding = nn.Parameter(scale * torch.randn(width))
        self.positional_embedding = nn.Parameter(scale * torch.randn((input_resolution // patch_size) ** 2 + 1, width))
        self.ln_pre = LayerNorm(width)
        self.transformer = Transformer(width, layers, heads, prompt_length=prompt_length, prompt_depth=prompt_depth)

        self.ln_post = LayerNorm(width)
        self.proj = nn.Parameter(scale * torch.randn(width, output_dim))

    def forward(self, x: torch.Tensor, all_prompts_image, missing_type): # all_prompts_image is a list of prompts per layer
        x = self.conv1(x)  # shape = [*, width, grid, grid]
        x = x.reshape(x.shape[0], x.shape[1], -1)  # shape = [*, width, grid ** 2]
        x = x.permute(0, 2, 1)  # shape = [*, grid ** 2, width]
        x = torch.cat(
            [self.class_embedding.to(x.dtype) + torch.zeros(x.shape[0], 1, x.shape[-1], dtype=x.dtype, device=x.device),
             x], dim=1)  # shape = [*, grid ** 2 + 1, width]
        x = x + self.positional_embedding.to(x.dtype)

        x = self.ln_pre(x)

        x = x.permute(1, 0, 2)  # NLD -> LND
        outputs = self.transformer([x, all_prompts_image, 0, missing_type])  # Pass prompts and counter to transformer
        x = outputs[0]
        x = x.permute(1, 0, 2)  # LND -> NLD

        # Extracts the class token, after the prompt tokens (prompt_length) in the sequence
        x = self.ln_post(x[:, self.prompt_length, :]) # Assuming prompt_length is the total length of prepended tokens including dynamic and common

        if self.proj is not None:
            x = x @ self.proj

        return x

class CLIP(nn.Module):
    def __init__(self,
                 embed_dim: int,
                 image_resolution: int,
                 vision_layers: Union[Tuple[int, int, int, int], int],
                 vision_width: int,
                 vision_patch_size: int,
                 context_length: int,
                 vocab_size: int,
                 transformer_width: int,
                 transformer_heads: int,
                 transformer_layers: int,
                 prompt_length, 
                 prompt_depth, 
                 ):
        super().__init__()

        self.context_length = context_length
        self.prompt_length = prompt_length

        if isinstance(vision_layers, (tuple, list)): # Only ViT path is fully implemented for brevity.
            raise NotImplementedError("ModifiedResNet (for ResNet backbone) is not implemented here for brevity in prompt integration.")
        else:
            vision_heads = vision_width // 64
            self.visual = VisionTransformer(
                    input_resolution=image_resolution,
                    patch_size=vision_patch_size,
                    width=vision_width,
                    layers=vision_layers,
                    heads=vision_heads,
                    output_dim=embed_dim,
                    prompt_length=prompt_length,
                    prompt_depth = prompt_depth,
                )
        self.transformer = Transformer(
            width=transformer_width,
            layers=transformer_layers,
            heads=transformer_heads,
            attn_mask=self.build_attention_mask(),
            text_layer=True,
            prompt_length=prompt_length,
            prompt_depth = prompt_depth,
        )

        self.vocab_size = vocab_size
        self.token_embedding = nn.Embedding(vocab_size, transformer_width)
        self.positional_embedding = nn.Parameter(torch.empty(self.context_length, transformer_width))
        self.ln_final = LayerNorm(transformer_width)

        self.text_projection = nn.Parameter(torch.empty(transformer_width, embed_dim))
        self.logit_scale = nn.Parameter(torch.ones([]) * np.log(1 / 0.07))

        self.initialize_parameters()

    def initialize_parameters(self):
        nn.init.normal_(self.token_embedding.weight, std=0.02)
        nn.init.normal_(self.positional_embedding, std=0.01)

        proj_std = (self.transformer.width ** -0.5) * ((2 * self.transformer.layers) ** -0.5)
        attn_std = self.transformer.width ** -0.5
        fc_std = (2 * self.transformer.width) ** -0.5
        for block in self.transformer.resblocks:
            nn.init.normal_(block.attn.in_proj_weight, std=attn_std)
            nn.init.normal_(block.attn.out_proj.weight, std=proj_std)
            nn.init.normal_(block.mlp.c_fc.weight, std=fc_std)
            nn.init.normal_(block.mlp.c_proj.weight, std=proj_std)

        if self.text_projection is not None:
            nn.init.normal_(self.text_projection, std=self.transformer.width ** -0.5)

    def build_attention_mask(self):
        # lazily create causal attention mask, with full attention between the vision tokens
        # pytorch uses additive attention mask; fill with -inf
        mask = torch.empty(self.context_length + self.prompt_length, self.context_length + self.prompt_length)
        mask.fill_(float("-inf"))
        mask.triu_(1)  # zero out the lower diagonal
        return mask

    @property
    def dtype(self):
        return self.visual.conv1.weight.dtype

    def encode_image(self, image, all_prompts_image, missing_type):
        return self.visual(image.type(self.dtype), all_prompts_image, missing_type)

    def encode_text(self, tokenized_texts, all_prompts_text, missing_type):
        x = self.token_embedding(tokenized_texts).type(self.dtype)  # [batch_size, n_ctx, d_model]

        x = x + self.positional_embedding.type(self.dtype)
        x = x.permute(1, 0, 2)  # NLD -> LND
        # Pass as the list, as nn.sequential cannot process multiple arguments in the forward pass
        combined = [x, all_prompts_text, 0, missing_type]  # third argument is the counter which denotes depth of prompt
        outputs = self.transformer(combined)
        x = outputs[0][self.prompt_length:]  # extract the x back from here, skipping prompt tokens
        x = x.permute(1, 0, 2)  # LND -> NLD
        x = self.ln_final(x).type(self.dtype)

        # x.shape = [batch_size, n_ctx, transformer.width]
        # take features from the eot embedding (eot_token is the highest number in each sequence)
        x = x[torch.arange(x.shape[0]), tokenized_texts.argmax(dim=-1)] @ self.text_projection

        return x

    def forward(self, image, text): # This base forward is generally unused when CustomCLIP is the entry point
        image_features = self.encode_image(image, [], None) # Simplified dummy arguments
        text_features = self.encode_text(text, [], None) # Simplified dummy arguments

        # normalized features
        image_features = image_features / image_features.norm(dim=-1, keepdim=True)
        text_features = text_features / text_features.norm(dim=-1, keepdim=True)

        # cosine similarity as logits
        logit_scale = self.logit_scale.exp()
        logits_per_image = logit_scale * image_features @ text_features.t()
        logits_per_text = logit_scale * text_features @ image_features.t()

        # shape = [global_batch_size, global_batch_size]
        return logits_per_image, logits_per_text

def build_model(state_dict: dict, prompt_length, prompt_depth):
    vit = "visual.proj" in state_dict

    if vit:
        vision_width = state_dict["visual.conv1.weight"].shape[0]
        vision_layers = len(
            [k for k in state_dict.keys() if k.startswith("visual.") and k.endswith(".attn.in_proj_weight")])
        vision_patch_size = state_dict["visual.conv1.weight"].shape[-1]
        grid_size = round((state_dict["visual.positional_embedding"].shape[0] - 1) ** 0.5)
        image_resolution = vision_patch_size * grid_size
    else:
        raise NotImplementedError("ResNet backbone is not fully implemented in this extracted snippet for brevity, focusing on ViT.")

    embed_dim = state_dict["text_projection"].shape[1]
    context_length = state_dict["positional_embedding"].shape[0]
    vocab_size = state_dict["token_embedding.weight"].shape[0]
    transformer_width = state_dict["ln_final.weight"].shape[0]
    transformer_heads = transformer_width // 64
    transformer_layers = len(set(k.split(".")[2] for k in state_dict if k.startswith(f"transformer.resblocks")))

    model = CLIP(
        embed_dim,
        image_resolution, vision_layers, vision_width, vision_patch_size,
        context_length, vocab_size, transformer_width, transformer_heads, transformer_layers, prompt_length, prompt_depth
    )

    for key in ["input_resolution", "context_length", "vocab_size"]:
        if key in state_dict:
            del state_dict[key]

    try:
        model.load_state_dict(state_dict)
    except:
        missing_keys, _ = model.load_state_dict(state_dict, strict=False)
    return model

