# Simplified BaseDataset for illustration, real version uses PyArrow tables.
class BaseDataset(torch.utils.data.Dataset):
    def __init__(
        self,
        data_dir: str,
        transform_keys: list,
        image_size: int,
        names: list,
        text_column_name: str = "",
        remove_duplicate=True,
        max_text_len=40,
        draw_false_image=0,
        draw_false_text=0,
        image_only=False,
        missing_ratio={},
        missing_type={},
    ):
        assert len(transform_keys) >= 1
        super().__init__()
        # Simplified transforms for illustration, actual implementation would require `keys_to_transforms`
        self.transforms = [Compose([Resize(image_size, interpolation=BICUBIC), CenterCrop(image_size), _convert_image_to_rgb, ToTensor(), Normalize((0.48145466, 0.4578275, 0.40821073), (0.26862954, 0.26130258, 0.27577711))])]
        self.text_column_name = text_column_name
        self.names = names
        self.max_text_len = max_text_len
        self.draw_false_image = draw_false_image
        self.draw_false_text = draw_false_text
        self.image_only = image_only
        self.data_dir = data_dir

        # Mock table and texts for brevity
        self.table = None 
        self.all_texts = [["This is a sample plot description for MMIMDB."]] * 100 
        self.index_mapper = {i: (i, 0) for i in range(100)} 

    def __len__(self):
        return len(self.index_mapper)

    def get_raw_image(self, index, image_key="image"):
        return Image.new('RGB', (224, 224), color = 'red') # Mock image

    def get_image(self, index, image_key="image"):
        image = self.get_raw_image(index, image_key=image_key)
        image_tensor = [tr(image) for tr in self.transforms]
        return {
            "image": image_tensor,
            "img_index": self.index_mapper[index][0],
            "cap_index": self.index_mapper[index][1],
            "raw_index": index,
        }

    def get_text(self, raw_index):
        index, caption_index = self.index_mapper[raw_index]
        text = self.all_texts[index][caption_index]
        return {
            "text": text,
            "img_index": index,
            "cap_index": caption_index,
            "raw_index": raw_index,
        }

    def collate(self, batch):
        # Simplified collate for illustration, handles core required fields for CLIPransformerSS
        batch_size = len(batch)
        img_tensors = [b['image'][0] if 'image' in b else torch.zeros(3,224,224) for b in batch]
        texts = [b['text'] if 'text' in b else '' for b in batch]
        labels = [b['label'] if 'label' in b else torch.zeros(23).int() for b in batch]
        missing_types = [b['missing_type'] if 'missing_type' in b else 0 for b in batch]

        return {
            "image": [torch.stack(img_tensors)],
            "text": [texts], # tokenize expects a list of strings within a list for batching
            "label": torch.stack([torch.tensor(l) for l in labels]),
            "missing_type": torch.tensor(missing_types),
        }

class MMIMDBDataset(BaseDataset):
    def __init__(self, *args, split="", missing_info={}, **kwargs):
        assert split in ["train", "val", "test"]
        self.split = split

        if split == "train":
            names = ["mmimdb_train"]
        elif split == "val":
            names = ["mmimdb_dev"]
        elif split == "test":
            names = ["mmimdb_test"]  

        super().__init__(
            *args,
            **kwargs,
            names=names,
            text_column_name="plots",
            remove_duplicate=False,
        )

        self.simulate_missing = missing_info['simulate_missing']
        missing_ratio = missing_info['ratio'][split]
        mratio = str(missing_ratio).replace('.','')
        missing_type_config = missing_info['type'][split]    
        both_ratio = missing_info['both_ratio']
        missing_table_root = missing_info['missing_table_root']
        missing_table_name = f'{names[0]}_missing_{missing_type_config}_{mratio}.pt'
        missing_table_path = os.path.join(missing_table_root, missing_table_name)

        # Mocking missing_table loading/creation
        total_num = len(self.index_mapper) # Use actual dataset length for mocking
        self.missing_table = torch.zeros(total_num)
        if missing_ratio > 0:
            missing_index = random.sample(range(total_num), int(total_num*missing_ratio))

            if missing_type_config == 'text':
                self.missing_table[missing_index] = 1
            elif missing_type_config == 'image':
                self.missing_table[missing_index] = 2
            elif missing_type_config == 'both':
                self.missing_table[missing_index] = 1
                missing_index_image  = random.sample(missing_index, int(len(missing_index)*both_ratio))
                self.missing_table[missing_index_image] = 2

        # Mock labels for MMIMDB for self-contained code
        self.table = {'label': [torch.randint(0, 2, (23,)).tolist() for _ in range(total_num)], 'image': [None]*total_num, 'plots': self.all_texts}

    def __getitem__(self, index):
        # index -> pair data index
        # image_index -> image index in table
        # question_index -> plot index in texts of the given image
        image_index, question_index = self.index_mapper[index]

        # For the case of training with modality-complete data
        # Simulate missing modality with random assign the missing type of samples
        simulate_missing_type = 0
        if self.split == 'train' and self.simulate_missing and self.missing_table[image_index] == 0:
            simulate_missing_type = random.choice([0,1,2])

        image_tensor = self.get_image(index)["image"]

        # missing image, dummy image is all-one image
        if self.missing_table[image_index] == 2 or simulate_missing_type == 2:
            for idx in range(len(image_tensor)):
                image_tensor[idx] = torch.ones(image_tensor[idx].size()).float()

        #missing text, dummy text is ''
        if self.missing_table[image_index] == 1 or simulate_missing_type == 1:
            text = ''
        else:
            text = self.get_text(index)["text"]


        labels = self.table["label"][image_index]

        return {
            "image": image_tensor,
            "text": text,
            "label": labels,
            "missing_type": self.missing_table[image_index].item()+simulate_missing_type,
        }

